import React from 'react';

const EmployeeList = ({ employees }) => {
  return (
    <div>
      <h3 className="text-lg font-semibold mb-4">Empleados Registrados</h3>
      <div className="space-y-3 max-h-96 overflow-y-auto">
        {employees.map((employee) => (
          <div key={employee.id} className="border border-gray-200 rounded-xl p-4 hover:shadow-md transition-shadow duration-200">
            <div className="flex justify-between items-start">
              <div className="flex-1">
                <h4 className="font-semibold text-gray-900">{employee.name}</h4>
                <p className="text-sm text-gray-600">{employee.position}</p>
                <p className="text-xs text-gray-500 mt-1">{employee.department}</p>
                <p className="text-xs text-blue-600 mt-1">{employee.email}</p>
              </div>
              <div className="text-right ml-4">
                <div className="text-sm font-medium text-gray-900">
                  {employee.entryTime}
                </div>
                <div className="flex items-center justify-end mt-1">
                  <span className={`inline-flex items-center px-2 py-1 text-xs font-medium rounded-full ${
                    employee.tardiness === 0 
                      ? 'bg-green-100 text-green-800' 
                      : 'bg-red-100 text-red-800'
                  }`}>
                    {employee.tardiness} min
                  </span>
                </div>
                <p className="text-xs text-gray-500 mt-1 font-mono">{employee.qrCode}</p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default EmployeeList;
